    // Helper method to validate the URL format and check for internal hosts
    private static boolean isValidUrl(String urlStr) {
        // Simple validation - in real scenarios, use a more robust validation library
        try {
            java.net.URL url = new java.net.URL(urlStr);
            // Check if the host is not an internal IP or localhost
            String host = url.getHost();
            return !host.equals("localhost") && !host.startsWith("127.") && !host.startsWith("192.168.") &&
                   !host.startsWith("10.") && !host.startsWith("172.16.");
        } catch (Exception e) {
            return false;
        }
    }
}
