// Secure: Validating and sanitizing input before using it in URL construction prevents SSRF
public class GoodExample {
    public static void main(String[] args) {
        try {
            // Validate and sanitize the input before using it in URL construction
            String userInput = "http://internal-api:8080/secret-data";
            if (isValidUrl(userInput)) {
                java.net.URL url = new java.net.URL(userInput);
                java.net.HttpURLConnection conn = (java.net.HttpURLConnection) url.openConnection();
                conn.setRequestMethod("GET");
                int responseCode = conn.getResponseCode();
                System.out.println("Response Code: " + responseCode);
            } else {
                System.out.println("Invalid or unsafe URL.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to validate the URL format and check for internal hosts
    private static boolean isValidUrl(String urlStr) {
        // Simple validation - in real scenarios, use a more robust validation library
        try {
            java.net.URL url = new java.net.URL(urlStr);
            // Check if the host is not an internal IP or localhost
            String host = url.getHost();
            return !host.equals("localhost") && !host.startsWith("127.") && !host.startsWith("192.168.") &&
                   !host.startsWith("10.") && !host.startsWith("172.16.");
        } catch (Exception e) {
            return false;
        }
    }
}
