// खराब कोड: अनुचित उपयोग के कारण सुविधा की कमी और सुरक्षा खतरा  
public class UserAuth {
    public boolean authenticate(String username, String password) {
        // अनुचित उपयोग: एक स्थानीय फ़ाइल में पासवर्ड के संग्रह के लिए असुरक्षित तरीका  
        String storedPassword = getPasswordFromFile(username);  
        return password.equals(storedPassword);  // कमजोर: कोई हैशिंग नहीं किया गया
    }

    private String getPasswordFromFile(String username) {
        // अनुचित उपयोग: फ़ाइल के आधार पर पासवर्ड के असुरक्षित प्राप्त करना  
        // इस तरह के डेटा के आधार पर अनुमान लगाने के लिए जाहिर है कि यह एक असुरक्षित विधि है  
        try {
            // एक असुरक्षित फ़ाइल से डेटा लेने के लिए एक सरल तरीका  
            return Files.readAllLines(Paths.get("users.txt")).get(0);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
