[代码片段 1]  
```java
// 易受攻击：直接使用用户输入作为查询参数，可能导致 SQL 注入漏洞
public String getUserData(String userInput) {
    // 构造 SQL 查询语句，未对输入进行验证或转义
    String query = "SELECT * FROM users WHERE username = '" + userInput + "'";

    // 假设此处执行了数据库查询操作（例如使用 JDBC）
    // 这种方式非常危险，因为用户可以注入恶意 SQL 语句
    return executeQuery(query);
}
```
***
[代码片段 2]  
```java
// 安全：使用预编译语句（PreparedStatement）防止 SQL 注入
public String getUserData(String userInput) {
    // 使用 PreparedStatement 来安全地处理用户输入
    String query = "SELECT * FROM users WHERE username = ?";

    try (Connection conn = getConnection(); PreparedStatement stmt = conn.prepareStatement(query)) {
        // 设置参数，避免直接拼接 SQL 字符串
        stmt.setString(1, userInput);

        // 执行查询并返回结果
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            return rs.getString("username");
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }

    return null;
}
```

