[frammento di codice 2]  
```java
// Corretto: utilizzo sicuro delle API Java con crittografia e validazione
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.util.Base64;

public class UserService {
    private String encryptedUsername;
    private String encryptedPassword;
    private static final String ALGORITHM = "AES";
    private static final String KEY = "MySecretKey12345"; // Chiave segreta (dovrebbe essere gestita in modo sicuro)

    public void setUserCredentials(String user, String pass) {
        try {
            Key key = new SecretKeySpec(KEY.getBytes(), ALGORITHM);
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, key);

            // Crittografia delle credenziali
            encryptedUsername = Base64.getEncoder().encodeToString(cipher.doFinal(user.getBytes()));
            encryptedPassword = Base64.getEncoder().encodeToString(cipher.doFinal(pass.getBytes()));
        } catch (Exception e) {
            throw new RuntimeException("Errore durante la crittografia", e);
        }
    }

    public boolean authenticate(String inputUser, String inputPass) {
        try {
            Key key = new SecretKeySpec(KEY.getBytes(), ALGORITHM);
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, key);

            // Decrittografia e confronto
            byte[] decryptedUser = cipher.doFinal(Base64.getDecoder().decode(encryptedUsername));
            byte[] decryptedPass = cipher.doFinal(Base64.getDecoder().decode(encryptedPassword));

            return new String(decryptedUser).equals(inputUser) && new String(decryptedPass).equals(inputPass);
        } catch (Exception e) {
            throw new RuntimeException("Errore durante l'autenticazione", e);
        }
    }
}
