[frammento di codice 2]  
```java
// Corretto: utilizzo sicuro delle API Java con validazione degli input
import java.util.Scanner;

public class Example {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String userInput = scanner.nextLine(); // Input non filtrato

        // Validazione dell'input prima dell'esecuzione di un comando
        if (isValidCommand(userInput)) {
            try {
                Process process = Runtime.getRuntime().exec(userInput);
                int exitCode = process.waitFor();
                System.out.println("Comando eseguito, codice di uscita: " + exitCode);
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Comando non valido o non autorizzato.");
        }
    }

    // Funzione per verificare se il comando è sicuro
    private static boolean isValidCommand(String command) {
        // Esempio semplice: permette solo comandi specifici
        return command.trim().startsWith("echo") || command.trim().startsWith("ls");
    }
}
